// A LIVE-HITBOX LAMP painted into the page. The whole question is 'is the blade out
// when the box goes live', and that is a per-FRAME fact — inferring it from a timestamp
// after the fact is exactly the kind of claim that should be shown, not asserted.
const el = document.createElement('div');
el.style.cssText = 'position:fixed;top:96px;left:290px;z-index:99999;font:bold 15px monospace;'
  + 'padding:5px 10px;border-radius:4px;color:#fff;background:#2a2a33';
document.body.appendChild(el); window.__lamp = el;
const paint = () => { const on = player1.hitboxes.some(h => h.delay <= 0);
  el.textContent = on ? '\u25CF HITBOX LIVE' : '\u25CB no hitbox';
  el.style.background = on ? '#c92c2c' : '#2a2a33';
  requestAnimationFrame(paint); };
requestAnimationFrame(paint);

// BEFORE = the flat numbers this commit replaced: delay 0.054s, active 0.2s.
// They were absolute, not ratios, so the 'before' fraction is derived per-fighter
// from that fighter's own heavy anim length.
window.__setMode = (mode) => { const fdH = 0.52;   // Kael's heavy anim, seconds
  if (mode === 'before') { FRAME_DATA.heavy.startup = 0.054 / fdH; FRAME_DATA.heavy.active = 0.20; }
  else                   { FRAME_DATA.heavy.startup = 0.42;        FRAME_DATA.heavy.active = 0.07; }
  return {mode, startupFrac:+FRAME_DATA.heavy.startup.toFixed(3), active:FRAME_DATA.heavy.active}; };

window.__heavy = () => new Promise(res => { const p1=player1, p2=player2;
  p1.hp=p1.maxHp; p2.hp=p2.maxHp; p1.x=380; p2.x=760; p1.facing=1; p2.facing=-1;
  p1.vx=0; p1.vy=0; p1.hitboxes.length=0; p1.recoveryTimer=0; p1.stunTimer=0;
  const t0=performance.now(); let live=null, off=null;
  p1.executeAttack(STATE.ATTACK_HEAVY);
  const tick=()=>{ const now=performance.now()-t0;
    const on = p1.hitboxes.some(h=>h.delay<=0);
    if(live===null && on) live=now;
    if(live!==null && off===null && !on) off=now;
    if(now<1200) requestAnimationFrame(tick);
    else res({ startupMs: live===null?null:Math.round(live),
               activeMs: (live!==null&&off!==null)?Math.round(off-live):null,
               startupFrames: live===null?null:+(live/16.67).toFixed(1),
               activeFrames: (live!==null&&off!==null)?+((off-live)/16.67).toFixed(1):null }); };
  requestAnimationFrame(tick); });
return 'armed'

// THE ACTUAL CLAIM: which animation cell is on screen the instant the box goes live.
// 13fps screen capture cannot resolve a 100ms difference; the engine can, exactly.
window.__heavyCell = () => new Promise(res => { const p1=player1,p2=player2;
  p1.hp=p1.maxHp; p1.x=380; p2.x=760; p1.facing=1; p2.facing=-1;
  p1.vx=0; p1.vy=0; p1.hitboxes.length=0; p1.recoveryTimer=0; p1.stunTimer=0;
  const t0=performance.now(); let done=false;
  p1.executeAttack(STATE.ATTACK_HEAVY);
  const tick=()=>{ const now=performance.now()-t0;
    if(!done && p1.hitboxes.some(h=>h.delay<=0)){ done=true;
      const a=p1.attackAnim;
      const el = a ? (animClock*1000 - a.start)/a.dur : null;
      return res({ liveAtMs:Math.round(now), liveAtFrames:+(now/16.67).toFixed(1),
                   animProgress: el===null?null:+el.toFixed(3),
                   cellOnScreen: el===null?null:attackCellIndex(el,6)+1,
                   ofCells:6 }); }
    if(now<1200) requestAnimationFrame(tick); else res({liveAtMs:null}); };
  requestAnimationFrame(tick); });
return 'cell probe armed'
